<script setup>
import {onMounted,reactive,ref} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import Icon from '../components/Icon.vue';
import {api,state,money,dateTime,labels,stages,loadConfig} from '../lib';
const route=useRoute(),router=useRouter(),order=ref(null),busy=ref(false),error=ref(''),usingLookup=ref(false),lookup=reactive({code:route.params.code||'',whatsapp:''});
async function load(source){if(source==='lookup')usingLookup.value=true;busy.value=true;error.value='';try{order.value=route.query.token&&!usingLookup.value?await api(`/orders/${route.params.code}`,{headers:{'x-tracking-token':route.query.token}}):await api('/orders/lookup',{method:'POST',body:lookup});}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(async()=>{await loadConfig().catch(()=>{});if(route.params.code&&route.query.token)load();});
function previous(){try{const last=JSON.parse(localStorage.getItem('teras-last-order'));if(last?.code&&last?.token)router.push({path:`/pesanan/${last.code}`,query:{token:last.token}});else error.value='Belum ada pesanan yang tersimpan di perangkat ini.';}catch{error.value='Belum ada pesanan yang tersimpan di perangkat ini.';}}
</script>
<template><div class="container inner-page tracking-page"><div class="tracking-heading"><span class="large-icon"><Icon :name="order?'CheckCircle2':'ReceiptText'" :size="32"/></span><h1 class="page-heading">{{order?'Pesananmu sudah kami terima.':'Pesanan saya'}}</h1><p class="page-intro">{{order?'Duduk santai. Pantau pesananmu dari halaman ini.':'Masukkan nomor pesanan dan WhatsApp untuk melihat status terbaru.'}}</p></div>
  <div v-if="error" class="alert error" role="alert">{{error}}</div>
  <div v-if="!order" class="panel lookup-panel"><form @submit.prevent="load('lookup')"><label>Nomor pesanan<input v-model="lookup.code" required placeholder="TT-20261030-XXXXXXXX" maxlength="24" @input="lookup.code=lookup.code.toUpperCase()"/></label><label>Nomor WhatsApp<input v-model="lookup.whatsapp" required type="tel" autocomplete="tel" placeholder="Nomor saat checkout"/></label><button class="button primary full" :disabled="busy">{{busy?'Mencari…':'Lacak pesanan'}}<Icon name="ArrowRight" :size="17"/></button></form><button class="text-button full" @click="previous">Buka pesanan terakhir di perangkat ini</button></div>
  <template v-else><section class="panel"><div class="order-heading"><div><small>NOMOR PESANAN</small><h2>{{order.code}}</h2><p>{{order.customer_name}} · {{order.order_type==='dine_in'?`Dine-in · Meja ${order.table_number}`:'Takeaway'}} · {{dateTime(order.created_at)}}</p></div><button class="button secondary" :disabled="busy" @click="load"><Icon name="RefreshCw" :size="16" :class="{spin:busy}"/>Perbarui status</button></div><ol class="order-timeline"><li v-for="(stage,i) in stages" :key="stage" :class="{done:stages.indexOf(order.status)>=i,current:order.status===stage}"><span><Icon v-if="stages.indexOf(order.status)>i" name="Check" :size="18"/><Icon v-else :name="['ReceiptText','Coffee','ShoppingBag','CheckCircle2'][i]" :size="18"/></span><strong>{{labels[stage]}}</strong></li></ol><div class="status-message"><Icon name="Info" :size="19"/><p>{{order.status==='received'?'Pesanan tercatat. Kasir akan memeriksa pembayaranmu.':order.status==='processing'?'Pesananmu sedang disiapkan oleh tim kami.':order.status==='ready'?(order.order_type==='dine_in'?'Pesanan siap diantar ke mejamu.':'Pesanan siap diambil di kasir.'):'Pesanan selesai. Terima kasih sudah singgah di Taman Teras!'}}</p></div><p class="secure-note">Tekan “Perbarui status” untuk melihat perubahan terbaru.</p></section>
  <div class="tracking-grid"><section class="panel"><h2>Detail pesanan</h2><div class="summary-line" v-for="item in order.items" :key="item.menu_id"><div><strong>{{item.quantity}}× {{item.name}}</strong><p v-if="item.note" class="muted small">Catatan: {{item.note}}</p></div><span>{{money(item.price*item.quantity)}}</span></div><div class="summary-total"><span>Total</span><strong>{{money(order.total)}}</strong></div></section><section class="panel payment-panel"><div class="section-title"><h2>Pembayaran</h2><span :class="['badge',order.payment_status==='paid'?'success':'warning']">{{order.payment_status==='paid'?'Lunas':'Belum dibayar'}}</span></div><p class="muted small">{{order.payment_method==='qris'?'QRIS':'Transfer bank'}} · {{money(order.total)}}</p><template v-if="order.payment_status!=='paid'"><div v-if="state.config?.mode==='demo'" class="alert">Mode demo: jangan melakukan pembayaran nyata. Kasir demo dapat menandai pesanan lunas.</div><template v-else-if="order.payment_method==='qris'"><img v-if="state.config?.payment.qris_image_url" class="payment-qr" :src="state.config.payment.qris_image_url" alt="QRIS resmi Taman Teras Cafe"/><p v-else class="alert">QRIS belum tersedia. Hubungi kasir.</p><p class="small">Scan QRIS cafe dan masukkan total yang sesuai. Kasir akan memverifikasi dana masuk.</p></template><template v-else><div v-if="state.config?.payment.account_number" class="bank-details"><small>{{state.config.payment.bank_name}}</small><strong>{{state.config.payment.account_number}}</strong><span>a.n. {{state.config.payment.account_holder}}</span></div><p v-else class="alert">Informasi rekening belum tersedia. Hubungi kasir.</p><p class="small">Transfer sesuai total pesanan. Status menjadi lunas setelah kasir memverifikasi.</p></template></template><p v-else class="payment-success"><Icon name="ShieldCheck" :size="22"/>Pembayaran sudah dikonfirmasi kasir.</p></section></div><RouterLink class="button secondary" to="/">Kembali ke menu <Icon name="ArrowRight" :size="17"/></RouterLink></template>
</div></template>
